<?php
require __DIR__.'/bootstrap.php';require_auth();if(!can('reports.view')){http_response_code(403);exit('Forbidden');}require __DIR__.'/partials.php';
$type=$_GET['type']??'invoice';$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$mode=$_GET['mode']??'';$channel=$_GET['channel']??'';$types=['invoice'=>'All Sales / Invoice-wise','product'=>'Item / Product-wise','category'=>'Category-wise','brand'=>'Brand-wise','customer'=>'Customer-wise','cashier'=>'Cashier-wise','method'=>'Payment Method-wise','credit'=>'Customer Credit & Outstanding','stock'=>'Current Stock & Value','purchase'=>'Purchases / Supplier-wise'];if(!isset($types[$type]))$type='invoice';if(!in_array($mode,['all','cash','credit'],true)){page_start('Reports','reports.php');?>
<section class="report-start"><span class="eyebrow">Step 1</span><h2>Which sales report do you want to see?</h2><p>Choose one. You can select invoice-wise, item-wise, category-wise and other details on the next screen.</p><div class="report-mode-cards"><a class="cash" href="?mode=cash&type=invoice"><span class="mode-icon">Rs</span><strong>Cash Sales</strong><small>Only sales paid fully at the time of sale</small><b>View Cash Reports →</b></a><a class="credit" href="?mode=credit&type=invoice"><span class="mode-icon">CR</span><strong>Credit Sales</strong><small>Credit invoices: paid, unpaid and partially paid</small><b>View Credit Reports →</b></a><a class="all" href="?mode=all&type=invoice"><span class="mode-icon">ALL</span><strong>Cash + Credit</strong><small>Both sale types together for the full business total</small><b>View All Sales Reports →</b></a></div></section><section class="report-flow"><span>1 Choose report</span><i>→</i><span>2 Choose details</span><i>→</i><span>3 Filter dates</span><i>→</i><span>4 Print or download</span></section><style>.report-start{background:#fff;border:1px solid #e3e8e2;border-radius:18px;padding:34px;box-shadow:0 12px 36px rgba(31,49,39,.07)}.report-start h2{font-size:28px;margin:8px 0}.report-start>p{color:#718078}.report-mode-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:28px}.report-mode-cards>a{min-height:230px;border:2px solid #e3e8e2;border-radius:16px;padding:24px;display:flex;flex-direction:column;align-items:flex-start}.report-mode-cards>a:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(31,49,39,.1)}.report-mode-cards strong{font-size:23px;margin:18px 0 7px}.report-mode-cards small{color:#718078;line-height:1.5;flex:1}.report-mode-cards b{margin-top:20px;color:#174e39}.report-mode-cards .cash{border-top:6px solid #2e9b58}.report-mode-cards .credit{border-top:6px solid #d18b2e}.report-mode-cards .all{border-top:6px solid #3973b7}.mode-icon{width:52px;height:52px;border-radius:50%;display:grid;place-items:center;background:#edf4e9;color:#174e39;font-weight:800}.report-flow{display:flex;align-items:center;justify-content:center;gap:14px;margin:22px 0;color:#718078;font-weight:700}.report-flow i{width:30px;height:30px;border-radius:50%;background:#cbe85b;color:#174e39;display:grid;place-items:center;font-style:normal}@media(max-width:800px){.report-mode-cards{grid-template-columns:1fr}.report-flow{flex-direction:column;text-align:center}.report-flow i{margin:auto;transform:rotate(90deg)}}</style><?php page_end();exit;}$payment=$mode==='all'?'':$mode;$saleWhere='DATE(s.sale_date) BETWEEN ? AND ? AND s.status NOT IN("cancelled","returned")';$params=[$from,$to];if(in_array($payment,['cash','credit'],true)){$saleWhere.=' AND s.payment_type=?';$params[]=$payment;}if(in_array($channel,['retail','wholesale'],true)){$saleWhere.=' AND s.sale_type=?';$params[]=$channel;}$metricWhere=$saleWhere;$metricParams=$params;$rows=[];
if($type==='invoice'){$sql='SELECT s.sale_no reference,COALESCE(c.name,"Walk-in") name,SUM(si.quantity) quantity,s.total sales,SUM(si.historical_unit_cost*si.quantity) cost,SUM(si.gross_profit) profit,s.status detail,s.id sale_id FROM sales s JOIN sale_items si ON si.sale_id=s.id LEFT JOIN customers c ON c.id=s.customer_id WHERE '.$saleWhere.' GROUP BY s.id ORDER BY s.sale_date DESC';}
elseif(in_array($type,['product','category','brand','customer','cashier'],true)){$map=['product'=>['p.item_code','p.name'],'category'=>['COALESCE(cat.name,"Uncategorised")','COALESCE(cat.name,"Uncategorised")'],'brand'=>['COALESCE(b.name,"No brand")','COALESCE(b.name,"No brand")'],'customer'=>['COALESCE(c.customer_code,"WALK-IN")','COALESCE(c.name,"Walk-in Customer")'],'cashier'=>['u.id','u.display_name']];[$ref,$name]=$map[$type];$sql="SELECT $ref reference,$name name,SUM(si.quantity) quantity,SUM(si.line_total) sales,SUM(si.historical_unit_cost*si.quantity) cost,SUM(si.gross_profit) profit,COUNT(DISTINCT s.id) detail,NULL sale_id FROM sales s JOIN sale_items si ON si.sale_id=s.id JOIN products p ON p.id=si.product_id LEFT JOIN categories cat ON cat.id=p.category_id LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN customers c ON c.id=s.customer_id JOIN users u ON u.id=s.created_by WHERE $saleWhere GROUP BY $ref,$name ORDER BY sales DESC";}
elseif($type==='method'){$sql='SELECT COALESCE(sp.method,"unpaid") reference,UPPER(REPLACE(COALESCE(sp.method,"unpaid"),"_"," ")) name,COUNT(DISTINCT s.id) quantity,COALESCE(SUM(sp.amount),0) sales,0 cost,0 profit,"payments" detail,NULL sale_id FROM sales s LEFT JOIN sale_payments sp ON sp.sale_id=s.id WHERE '.$saleWhere.' GROUP BY sp.method ORDER BY sales DESC';}
elseif($type==='credit'){$sql='SELECT s.sale_no reference,c.name name,1 quantity,s.total sales,SUM(si.historical_unit_cost*si.quantity) cost,SUM(si.gross_profit) profit,CONCAT("Outstanding: ",FORMAT(s.balance,2)," | Due: ",COALESCE(DATE_FORMAT(s.due_date,"%d %b %Y"),"not set")) detail,s.id sale_id FROM sales s JOIN customers c ON c.id=s.customer_id JOIN sale_items si ON si.sale_id=s.id WHERE '.$saleWhere.' AND s.payment_type="credit" GROUP BY s.id ORDER BY s.balance DESC';}
elseif($type==='stock'){$sql='SELECT p.item_code reference,p.name name,p.current_stock quantity,p.current_stock*p.retail_price sales,p.current_stock*p.avg_cost cost,p.current_stock*(p.retail_price-p.avg_cost) profit,IF(p.current_stock<=p.minimum_stock,"Low stock","Available") detail,NULL sale_id FROM products p WHERE p.status="active" ORDER BY p.current_stock*p.avg_cost DESC';$params=[];}
else{$sql='SELECT s.supplier_code reference,s.name name,SUM(pi.quantity) quantity,SUM(pi.line_total) sales,0 cost,0 profit,CONCAT(COUNT(DISTINCT p.id)," invoices | Owed: ",FORMAT(s.outstanding,2)) detail,NULL sale_id FROM purchases p JOIN suppliers s ON s.id=p.supplier_id JOIN purchase_items pi ON pi.purchase_id=p.id WHERE p.purchase_date BETWEEN ? AND ? AND p.status="posted" GROUP BY s.id ORDER BY sales DESC';$params=[$from,$to];}
$stmt=$db->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();$totalQty=array_sum(array_map(fn($r)=>(float)$r['quantity'],$rows));$totalSales=array_sum(array_map(fn($r)=>(float)$r['sales'],$rows));$totalCost=array_sum(array_map(fn($r)=>(float)$r['cost'],$rows));$totalProfit=array_sum(array_map(fn($r)=>(float)$r['profit'],$rows));$money=['invoiced'=>0,'cash_sales'=>0,'credit_sales'=>0,'collected'=>0,'credit_collected'=>0,'credit_expected'=>0,'outstanding'=>0,'collected_profit'=>0];$metric=$db->prepare('SELECT COALESCE(SUM(s.total),0) invoiced,COALESCE(SUM(CASE WHEN s.payment_type="cash" THEN s.total ELSE 0 END),0) cash_sales,COALESCE(SUM(CASE WHEN s.payment_type="credit" THEN s.total ELSE 0 END),0) credit_sales,COALESCE(SUM(s.paid_amount),0) collected,COALESCE(SUM(CASE WHEN s.payment_type="credit" THEN s.paid_amount ELSE 0 END),0) credit_collected,COALESCE(SUM(CASE WHEN s.payment_type="credit" THEN s.balance ELSE 0 END),0) credit_expected,COALESCE(SUM(x.profit*(CASE WHEN s.total>0 THEN s.paid_amount/s.total ELSE 0 END)),0) collected_profit FROM sales s JOIN (SELECT sale_id,SUM(gross_profit) profit FROM sale_items GROUP BY sale_id) x ON x.sale_id=s.id WHERE '.$metricWhere);$metric->execute($metricParams);$money=$metric->fetch()?:$money;$money['outstanding']=(float)$db->query('SELECT COALESCE(SUM(outstanding),0) FROM customers WHERE status="active"')->fetchColumn();
if(isset($_GET['export'])){$filename=preg_replace('/[^a-z0-9]+/i','-',strtolower($types[$type])).'-'.$from.'-'.$to.'.csv';header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$filename.'"');$out=fopen('php://output','w');fputcsv($out,[$types[$type],$from.' to '.$to]);fputcsv($out,['Reference','Name','Quantity / Count','Sales / Value','Saved Cost','Gross Profit','Details']);foreach($rows as $r)fputcsv($out,[$r['reference'],$r['name'],$r['quantity'],$r['sales'],$r['cost'],$r['profit'],$r['detail']]);fputcsv($out,['TOTAL','',$totalQty,$totalSales,$totalCost,$totalProfit,'']);fclose($out);exit;}
page_start('Reports','reports.php');?>
<section class="report-mode-switch"><a href="reports.php">← Choose again</a><span>Viewing:</span><a href="?mode=cash&type=<?=e($type)?>&from=<?=e($from)?>&to=<?=e($to)?>" class="<?=$mode==='cash'?'active cash':''?>">Cash Sales</a><i>→</i><a href="?mode=credit&type=<?=e($type)?>&from=<?=e($from)?>&to=<?=e($to)?>" class="<?=$mode==='credit'?'active credit':''?>">Credit Sales</a><i>→</i><a href="?mode=all&type=<?=e($type)?>&from=<?=e($from)?>&to=<?=e($to)?>" class="<?=$mode==='all'?'active all':''?>">Cash + Credit</a></section>
<style>.report-mode-switch{display:flex;align-items:center;gap:10px;background:#fff;border:1px solid #e3e8e2;border-radius:13px;padding:11px 14px;margin-bottom:18px}.report-mode-switch>a{padding:9px 12px;border-radius:8px;font-weight:700}.report-mode-switch>a:first-child{margin-right:auto;color:#174e39;background:#edf4e9}.report-mode-switch>a.active{color:#fff;background:#174e39}.report-mode-switch>a.active.credit{background:#a96d1e}.report-mode-switch>a.active.all{background:#3973b7}.report-mode-switch i{width:25px;height:25px;border-radius:50%;background:#cbe85b;color:#174e39;display:grid;place-items:center;font-style:normal}@media(max-width:750px){.report-mode-switch{align-items:stretch;flex-direction:column}.report-mode-switch>a:first-child{margin:0}.report-mode-switch i{margin:auto;transform:rotate(90deg)}}</style><script>document.addEventListener('DOMContentLoaded',()=>{const mode=<?=json_encode($mode)?>,label=mode==='cash'?'Cash Sales Only':(mode==='credit'?'Credit Sales Only':'Cash + Credit Sales');document.querySelectorAll('.report-tabs a').forEach(a=>{const u=new URL(a.href);u.searchParams.set('mode',mode);a.href=u});const form=document.querySelector('.report-filter');if(form){const hidden=document.createElement('input');hidden.type='hidden';hidden.name='mode';hidden.value=mode;form.appendChild(hidden);const payment=form.querySelector('select[name="payment"]');if(payment){payment.value=mode==='all'?'':mode;payment.disabled=true;const title=payment.closest('label');if(title)title.firstChild.textContent='Selected Sales ('+label+')'}}const eyebrow=document.querySelector('.report-head .eyebrow');if(eyebrow)eyebrow.textContent=mode==='cash'?'CASH SALES REPORT':(mode==='credit'?'CREDIT SALES REPORT':'ALL SALES REPORT')});</script>
<section class="report-head"><div><span class="eyebrow">Choose how to view the business</span><h2><?=e($types[$type])?></h2></div><div><a class="btn secondary" href="?<?=e(http_build_query(array_merge($_GET,['export'=>1])))?>">Download Excel/CSV</a> <button class="btn primary" onclick="window.print()">Print / Save PDF</button></div></section><section class="report-tabs"><?php foreach($types as $key=>$label):?><a href="?type=<?=$key?>&from=<?=e($from)?>&to=<?=e($to)?>" class="<?=$type===$key?'active':''?>"><?=e($label)?></a><?php endforeach;?></section><section class="panel"><form class="report-filter"><input type="hidden" name="type" value="<?=e($type)?>"><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><label>Cash / Credit<select name="payment"><option value="">All</option><option value="cash" <?=$payment==='cash'?'selected':''?>>Cash</option><option value="credit" <?=$payment==='credit'?'selected':''?>>Credit</option></select></label><label>Retail / Wholesale<select name="channel"><option value="">All</option><option value="retail" <?=$channel==='retail'?'selected':''?>>Retail</option><option value="wholesale" <?=$channel==='wholesale'?'selected':''?>>Wholesale</option></select></label><button class="btn primary">Apply Filters</button></form></section><?php if(!in_array($type,['stock','purchase'],true)):?><section class="money-explanation"><b>Sales value and expected credit are separate:</b> All Sales = Cash Sales + original Credit Sales. Collected from Credit Sales increases whenever a customer payment is received, while Customer Receivables decreases.</section><section class="kpi-grid report-kpis six"><article class="kpi money-card expected"><span>All Sales Total</span><strong><?=money($money['invoiced'])?></strong><small>Cash sales + original credit invoices</small></article><article class="kpi money-card collected"><span>Cash Sales Total</span><strong><?=money($money['cash_sales'])?></strong><small>Invoices created as cash sales</small></article><article class="kpi money-card profit"><span>Credit Sales Total</span><strong><?=money($money['credit_sales'])?></strong><small>Original value of credit invoices</small></article><article class="kpi money-card collected"><span>Total Money Collected</span><strong><?=money($money['collected'])?></strong><small>Cash sales + payments received on credit</small></article><article class="kpi money-card collected"><span>Collected from Credit Sales</span><strong><?=money($money['credit_collected'])?></strong><small>Initial and later payments received for credit invoices</small></article><article class="kpi money-card outstanding"><span>Current Customer Receivables</span><strong><?=money($money['outstanding'])?></strong><small>Includes opening credit balances</small></article><article class="kpi money-card profit"><span>Expected Gross Profit</span><strong><?=money($totalProfit)?></strong><small>Collected-backed profit: <?=money($money['collected_profit'])?></small></article></section><?php else:?><section class="kpi-grid report-kpis"><article class="kpi"><span>Quantity</span><strong><?=number_format($totalQty,3)?></strong></article><article class="kpi"><span>Total Value</span><strong><?=money($totalSales)?></strong></article><article class="kpi"><span>Stock / Saved Cost</span><strong><?=money($totalCost)?></strong></article><article class="kpi"><span>Potential Profit</span><strong><?=money($totalProfit)?></strong></article></section><?php endif;?><section class="panel table-panel"><div class="panel-head"><div><span class="eyebrow">Full details</span><h3><?=count($rows)?> row(s)</h3></div></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Name</th><th class="right">Qty / Count</th><th class="right">Sales / Value</th><th class="right">Saved Cost</th><th class="right">Gross Profit</th><th>Details</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8"><div class="empty-state compact"><b>No records for these filters</b></div></td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><b><?=e($r['reference'])?></b></td><td><?=e($r['name'])?></td><td class="right"><?=number_format((float)$r['quantity'],3)?></td><td class="right"><?=money($r['sales'])?></td><td class="right"><?=money($r['cost'])?></td><td class="right"><b><?=money($r['profit'])?></b></td><td><?php $statusKey=strtolower(str_replace(' ','_',(string)$r['detail']));if(in_array($statusKey,['paid','unpaid','partially_paid','overdue'],true)):?><span class="status status-<?=e($statusKey)?>"><?=e(ucwords(str_replace('_',' ',$statusKey)))?></span><?php else:?><?=e($r['detail'])?><?php endif;?></td><td><?php if($r['sale_id']):?><a href="sale_view.php?id=<?=$r['sale_id']?>">View</a><?php endif;?></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="2">TOTAL</th><th class="right"><?=number_format($totalQty,3)?></th><th class="right"><?=money($totalSales)?></th><th class="right"><?=money($totalCost)?></th><th class="right"><?=money($totalProfit)?></th><th colspan="2"></th></tr></tfoot></table></div></section><style>.report-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:16px}.report-head h2{margin:5px 0}.report-tabs{display:flex;gap:8px;overflow-x:auto;padding-bottom:10px}.report-tabs a{background:#fff;border:1px solid #e3e8e2;padding:10px 13px;border-radius:9px;white-space:nowrap;font-weight:700;font-size:12px}.report-tabs a.active{background:#174e39;color:#fff}.report-filter{display:flex;gap:12px;align-items:end}.report-kpis{margin-top:18px}.report-kpis.six{grid-template-columns:repeat(3,minmax(0,1fr))}@media(max-width:1100px){.report-kpis.six{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.report-kpis.six{grid-template-columns:1fr}}.money-explanation{margin-top:16px;padding:13px 16px;background:#eef4f8;border-left:4px solid #3973b7;border-radius:7px;color:#526170}tfoot th{background:#edf4e9}@media(max-width:800px){.report-head,.report-filter{align-items:stretch;flex-direction:column}}@media print{.sidebar,.topbar,.report-tabs,.report-filter,.report-head .btn{display:none!important}.app{margin:0!important;width:100%!important}.content{padding:0!important}}</style><?php page_end();
